+/// (registry name, .cps stem) of each shipped post, in registry order.
+fn registry() -> Vec<(&'static str, &'static str)> {
+    posting::BUILTINS
+        .iter()
+        .map(|(name, file)| {
+            let stem = file.0.strip_suffix(".cps").unwrap_or_else(|| panic!("{name}: {} is not a .cps file", file.0));
