+/// Fanuc's goldens are at the top of `golden/nc/` (M1.7b); each other
+/// milling dialect has a subdirectory with its stem as the name.
+fn golden_subdir(stem: &'static str) -> &'static str {
+    if stem == "fanuc" { "" } else { stem }
